13	// GenerateText sends a prompt to the Claude CLI and returns the raw text response.
14	// Implements the agent.TextGenerator interface.
15	// The model parameter hints which model to use (e.g., "haiku", "sonnet").
16	// If empty, defaults to "haiku" for fast, cheap generation.
17	func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
18		claudePath := "claude"
19		if model == "" {
20			model = "haiku"
21		}
22	
23		commandRunner := c.CommandRunner
24		if commandRunner == nil {
25			commandRunner = exec.CommandContext
26		}
27	
28		cmd := commandRunner(ctx, claudePath,
29			"--print", "--output-format", "json",
30			"--model", model, "--setting-sources", "")
31	
32		// Isolate from the user's git repo to prevent recursive hook triggers
33		// and index pollution (same approach as summarize/claude.go).
34		cmd.Dir = os.TempDir()
35		cmd.Env = stripGitEnv(os.Environ())
36		cmd.Stdin = strings.NewReader(prompt)
37	
38		var stdout, stderr bytes.Buffer
39		cmd.Stdout = &stdout
40		cmd.Stderr = &stderr
41	
42		if err := cmd.Run(); err != nil {
43			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
44				return "", context.DeadlineExceeded
45			}
46			if errors.Is(ctx.Err(), context.Canceled) {
47				return "", context.Canceled
48			}
49			if isExecNotFound(err) {
50				return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
51			}
52			// Non-zero exit: try to parse stdout for a structured error envelope,
53			// then fall back to stderr classification.
54			if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
55				result := ""
56				if env.Result != nil {
57					result = *env.Result
58				}
59				exitCode := 0
60				var exitErr *exec.ExitError
61				if errors.As(err, &exitErr) {
62					exitCode = exitErr.ExitCode()
63				}
64				return "", classifyEnvelopeError(result, env.APIErrorStatus, exitCode)
65			}
66			exitCode := -1
67			var exitErr *exec.ExitError
68			if errors.As(err, &exitErr) {
69				exitCode = exitErr.ExitCode()
70			}
71			return "", classifyStderrError(stderr.String(), exitCode)
72		}
73	
74		// Exit 0: parse the response and check for is_error (Claude CLI returns
75		// most operational errors as exit 0 with is_error:true in the envelope).
76		result, env, err := parseGenerateTextResponse(stdout.Bytes())
77		if err != nil {
78			return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: fmt.Sprintf("failed to parse claude CLI response: %v", err), Cause: err}
79		}
80		if env != nil && env.IsError {
81			return "", classifyEnvelopeError(result, env.APIErrorStatus, 0)
82		}
83	
84		return result, nil
85	}
