87	// isExecNotFound returns true if err indicates the subprocess binary could not be found.
88	// Covers both PATH-based lookups (*exec.Error / exec.ErrNotFound) and absolute-path
89	// failures (*fs.PathError wrapping os.ErrNotExist on macOS/Linux).
90	func isExecNotFound(err error) bool {
91		var execErr *exec.Error
92		if errors.As(err, &execErr) {
93			return true
94		}
95		return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
96	}
