98	// stripGitEnv returns a copy of env with all GIT_* variables removed.
99	// This prevents a subprocess from discovering or modifying the parent's git repo.
100	// Duplicated from summarize/claude.go — simple filter not worth extracting to shared package.
101	func stripGitEnv(env []string) []string {
102		filtered := make([]string, 0, len(env))
103		for _, e := range env {
104			if !strings.HasPrefix(e, "GIT_") {
105				filtered = append(filtered, e)
106			}
107		}
108		return filtered
109	}
