520	func generateCheckpointAISummary(ctx context.Context, scopedTranscript []byte, filesTouched []string, agentType types.AgentType) (*checkpoint.Summary, error) {
521		timeoutCtx, cancel := context.WithTimeout(ctx, checkpointSummaryTimeout)
522		timeoutDuration := checkpointSummaryTimeout
523		if deadline, ok := timeoutCtx.Deadline(); ok {
524			timeoutDuration = time.Until(deadline)
525		}
526		defer cancel()
527	
528		// scopedTranscript is read from checkpoint storage, which redacts on write.
529		summary, err := generateTranscriptSummary(timeoutCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, agentType, nil)
530		if err != nil {
531			if errors.Is(err, context.Canceled) || errors.Is(timeoutCtx.Err(), context.Canceled) {
532				return nil, fmt.Errorf("summary generation canceled: %w", context.Canceled)
533			}
534			if errors.Is(err, context.DeadlineExceeded) || errors.Is(timeoutCtx.Err(), context.DeadlineExceeded) {
535				return nil, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(timeoutDuration), context.DeadlineExceeded)
536			}
537			return nil, err
538		}
539	
540		return summary, nil
541	}
